def palindrome_permutations(s):
    ht = {}
    for i in range(len(s)):
        c = s[i]
        restored = s[:i] + c + s[i+1:]
        if restored in ht:
            continue
        ht[restored] = None
        if restored.startswith(c):
            yield restored
    return ht

