    stack = []
    result = []
    current_group = ""

    for char in paren_string:
        if char in open_brackets:
            stack.append(open_brackets[char])
            if current_group:
                result.append(current_group)
                current_group = ""
        elif char in open_brackets.values():
            if not stack or char != stack.pop():
                return []
        else:
            current_group += char

    if stack:
        return []

