def median(l: list, cmp_func: callable):
    if not l:
        return None

    def partition(arr, low, high):
        pivot = arr[high]
        i = low - 1
        for j in range(low, high):
            if cmp_func(arr[j], pivot) < 0:
                i += 1
                arr[i], arr[j] = arr[j], arr[i]
        arr[i + 1], arr[high] = arr[high], arr[i + 1]
        return i + 1

    def kth_smallest(arr, low, high, k):
        if k > 0 and k <= high - low + 1:
            pos = partition(arr, low, high)
            if pos - low == k - 1:
                return arr[pos]
            if pos - low > k - 1:
                return kth_smallest(arr, low, pos - 1, k)
            return kth_smallest(arr, pos + 1, high, k - pos + low - 1)

    n = len(l)
    if n % 2 == 1:
        return kth_smallest(l, 0, n - 1, n // 2 + 1)
    else:
