def findKthBit(n, k):
    # Base case: If we're looking at the first string, the answer is always "0"
    if n == 1:
        return "0"

    # Calculate the length of the current string Sn
    length = 2**n - 1

    # Find the middle position of Sn
    middle = length // 2 + 1

    # If k is exactly in the middle, the bit is "1"
    if k == middle:
        return "1"
    # If k is in the first half of Sn, it's the same as finding the kth bit in Sn-1
    elif k < middle:
        return findKthBit(n-1, k)
    # If k is in the second half of Sn, find its mirrored position in the first half and invert the result
    else:
        # Calculate the mirrored position in the first half
        mirrored_pos = length - k + 1
        # Recursively find the bit at the mirrored position in Sn-1 and invert it
        return "0" if findKthBit(n-1, mirrored_pos) == "1" else "1"

