def find_min_diff(A, left=None, right=None, m=float('inf')):
    # Base case: leaf node, return infinity
    if left is None and right is None:
        return float('inf')

    # If the subarray does not contain any odd indexed elements, return infinity
    if (A[left] % 2 == 0) or (A[right] % 2 == 0):
        return float('inf')

    # If the subarray has only one element, return the absolute difference with infinity
    if left == right:
        return abs(A[left] - A[right-1]) if A[right-1] > m else float('inf')

    # If the subarray has two elements, compare them and return the minimum
    elif left + 1 == right:
        return min(abs(A[left] - A[right-1]),
                   abs(A[right] - A[left+1]))

    else:
        # Split the array and recursively find the minimum absolute difference
        mid = (left + right) // 2
        left_min = find_min_diff(A, left, mid, m)
        right_min = find_min_diff(A, mid + 1, right, m)

        # Return the minimum of the two recursive calls
        return min(left_min, right_min)

