def can_partition(nums):
    total_sum = sum(nums)
    # If the total sum is odd, it cannot be partitioned into two equal sums
    if total_sum % 2 != 0:
        return []

    target = total_sum // 2
    n = len(nums)
    dp = [[False] * (target + 1) for _ in range(n + 1)]
    dp[0][0] = True

    for i in range(1, n + 1):
        for j in range(target + 1):
            if j >= nums[i-1]:
                dp[i][j] = dp[i-1][j] or dp[i-1][j-nums[i-1]]
            else:
                dp[i][j] = dp[i-1][j]

    if not dp[n][target]:
        return []

    # Backtrack to find the elements in the partition
    partition = []
    while target != 0:
        for i in range(n, 0, -1):
            if dp[i][target] and not dp[i-1][target]:
                partition.append(nums[i-1])
                target -= nums[i-1]
                n = i-1
                break

    # Create the second partition by removing the elements of the first partition from the original array
    remaining = nums[:]
    for num in partition:
        remaining.remove(num)

    return [partition, remaining]

